// LightSearchBar.tsx
const LightSearchBar = React.memo(function LightSearchBar(){
  const [local, setLocal] = useState('');
  const { dispatch } = useContext(FilterContext);
  const debounced = useDebounce(local, 250);
  useEffect(()=>{ if(debounced !== undefined){ dispatch({ type: 'SET_QUERY', payload: debounced }); }}, [debounced]);
  return <input value={local} onChange={e=>setLocal(e.target.value)} />;
});
